import django.core.validators
from decimal import Decimal
from django.db import migrations, models


def enable_public_riders_for_shops_without_riders(apps, schema_editor):
    Shop = apps.get_model("seller", "Shop")
    ShopStaff = apps.get_model("seller", "ShopStaff")
    database = schema_editor.connection.alias
    for shop in Shop.objects.using(database).all().iterator():
        has_active_rider = ShopStaff.objects.using(database).filter(
            shop_id=shop.pk,
            role="RIDER",
            is_active=True,
            is_public_rider=False,
        ).exists()
        if not has_active_rider:
            Shop.objects.using(database).filter(pk=shop.pk).update(
                public_rider_network_enabled=True,
                rider_delivery_preference="PUBLIC",
            )


